"""Custom FastAPI application exposing in-memory metrics endpoints.

This FastAPI app is mounted onto the Reflex backend through the
``api_transformer`` parameter of ``rx.App``.  It owns a small set of
in-process counters and exposes two JSON endpoints:

* ``GET /api/metrics``            - return all counters and their total.
* ``POST /api/metrics/increment`` - increment a named counter.

All state lives in ordinary process memory; there are no external
services, databases, or network dependencies.  The counters reset to 0
whenever the server process restarts.
"""

from fastapi import FastAPI
from fastapi.responses import JSONResponse
from pydantic import BaseModel

# The fixed set of counters, held entirely in process memory and owned
# by this FastAPI layer.  Insertion order is preserved so the JSON
# response lists the counters in a stable, deterministic order.
_counters: dict[str, int] = {
    "page_view": 0,
    "button_click": 0,
    "api_call": 0,
}

# The set of valid counter names, derived from the initial counters.
_VALID_COUNTERS = frozenset(_counters)


class IncrementRequest(BaseModel):
    """Request body for ``POST /api/metrics/increment``."""

    name: str
    amount: int = 1


def create_metrics_app() -> FastAPI:
    """Build the FastAPI application that serves the metrics endpoints."""
    app = FastAPI(title="Live Metrics Dashboard API")

    @app.get("/api/metrics")
    def get_metrics() -> JSONResponse:
        """Return the current counters and their aggregate total."""
        total = sum(_counters.values())
        return JSONResponse(
            {
                "counters": dict(_counters),
                "total": total,
            }
        )

    @app.post("/api/metrics/increment")
    def increment_metric(request: IncrementRequest) -> JSONResponse:
        """Increment a named counter by ``amount`` and return the new value."""
        name = request.name
        if name not in _VALID_COUNTERS:
            return JSONResponse(
                {"detail": f"Unknown counter: {name}"}, status_code=404
            )
        _counters[name] += request.amount
        total = sum(_counters.values())
        return JSONResponse(
            {"name": name, "value": _counters[name], "total": total}
        )

    return app


# A module-level instance that is passed to ``rx.App(api_transformer=...)``.
metrics_api: FastAPI = create_metrics_app()

